import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Wan: Open and Advanced Large-Scale Video Generative Models","description":"","frontmatter":{"title":"Wan: Open and Advanced Large-Scale Video Generative Models","arxiv":"2503.20314","date":"2025-03-26","authors":"Wan Team（Alibaba Group）","categories":"cs.CV","topics":"开源视频基础模型, 因果 3D VAE, 训练系统","outline":[2,2]},"headers":[],"relativePath":"papers/2503.20314.md","filePath":"papers/2503.20314.md","lastUpdated":null}'),e={name:"papers/2503.20314.md"};function l(m,s,i,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="wan-open-and-advanced-large-scale-video-generative-models" tabindex="-1">Wan: Open and Advanced Large-Scale Video Generative Models <a class="header-anchor" href="#wan-open-and-advanced-large-scale-video-generative-models" aria-label="Permalink to &quot;Wan: Open and Advanced Large-Scale Video Generative Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.20314" target="_blank" rel="noreferrer">2503.20314</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-26（v2 修订于 2025-04-19；60 页 / 33 图）</td></tr><tr><td><strong>作者</strong></td><td>Wan Team（Alibaba Group，论文以团队名义署名）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 127M 参数的 3D 因果 VAE（RMSNorm + feature cache，支持任意长度分块编解码）配 shared-AdaLN 的 DiT + flow matching，把视频基础模型做成 1.3B / 14B 两档全开源套件，1.3B 只要 8.19GB 显存。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/autoregressive">自回归视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本页依据 <strong>v2</strong>（2025-04-19）全文撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>作者把开源视频模型与闭源模型之间的差距拆成三条具体缺口，而不是笼统地说&quot;效果差&quot;：<strong>性能</strong>上闭源迭代速度远快于开源；<strong>能力</strong>上多数开源基础模型只做通用 text-to-video，而真实创作需求是多任务的（image-to-video、指令式视频编辑、个性化定制等）；<strong>效率</strong>上模型太大，普通人跑不动。</p><p>这三条缺口决定了一份开源工作真正该交付什么。如果只放一个 T2V 权重，社区能做的只有 prompt 工程；而如果同时给出 VAE、训练配方、分布式策略、数据清洗流程、评测基准与一个能塞进消费级显卡的小模型，下游的后训练工作（AR 蒸馏、缓存加速、长视频扩展）才有底座可用。Wan 的定位就是后者——它把自己写成一份系统报告而非单点方法论文，这也是它后来成为 Self-Forcing、LongLive、CausVid 一类 AR 工作默认底座的原因。</p><p>另外一件此前开源侧没做到的事：Wan 声称是第一个能在视频中生成中英文视觉文字的模型。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>HunyuanVideo、Mochi、CogVideoX</strong> 是最直接的对照，它们已经把代码与权重公开，缩小了与商用模型的差距。但论文指出的问题在两处。一是 VAE：主流做法都是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 压缩、latent 维度 16，而重建速度与显存开销并没有被认真优化——Wan 报告在同一硬件下其 VAE 重建速度是 HunyuanVideo 的 2.5 倍。二是能力覆盖：这些模型主要停在 T2V。</p><p><strong>文本编码器</strong>这条线上，主流选择是 T5 系列，常与 CLIP 并用；HunyuanVideo 则把 T5 换成 MLLM 以求文本与视觉特征更强的对齐。作者在这里给出了一个反向的经验结论（见 §7），并解释了原因：decoder-only 的 LLM 用因果注意力，而 umT5 是双向注意力，更适配 diffusion。他们照 HunyuanVideo 的做法给 Qwen2.5-7B-Instruct 与 GLM-4-9B 加了双向 token refiner 适配层，仍不如 umT5。</p><p><strong>架构层面</strong>，U-Net 被改造出时间维用于视频，也有工作（1D 时间注意力 + 2D 空间注意力）拿分解注意力换计算量；纯 transformer 的 DiT 被认为在视觉生成上优于 U-Net。Wan 不在这一层做新东西，它选定 DiT + Flow Matching 这个已被 T2I/T2V 双双验证过 scaling 收益的组合，把精力放在 VAE、数据与系统上。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一个约束来自算力账本。论文自己算过：DiT 部分占训练总计算量 85% 以上；在 100 万 token、micro-batch 为 1 时，14B DiT 的激活值就超过 8 TB。这个数字直接决定了&quot;先做什么&quot;——任何能减少 token 数或减少每 token 开销的设计，收益都远大于在 DiT 结构上微调。于是 VAE 成了第一优先级。</p><p>第二个约束来自长视频。如果 VAE 必须一次吃进整段视频，显存就随时长线性爆炸。要支持任意长度，编解码必须分块；而分块又会破坏时间连续性。这两个要求合起来指向一个具体设计：分块处理 + 跨块保留 feature cache。但 cache 要成立，网络里就不能有跨越整段序列做统计的算子——GroupNorm 正是这样的算子。把它换成 RMSNorm 不是随手的替换，而是让 cache 机制成立的前提。</p><p>第三个约束来自训练稳定性。直接用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1280</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">720</span></span></span></span>、81 帧联合训练有两个后果：序列太长导致固定 GPU-hour 预算下吞吐不够、收敛不了；显存占用逼得 batch size 过小，梯度方差尖峰造成不稳。所以必须从低分辨率图像起步，逐级抬分辨率。</p><p>第四个约束来自评测。要在&quot;哪个模型更好&quot;上做决策，就得有一把尺子；而现有 benchmark 各维度权重与人类偏好未必一致。于是作者做了 Wan-Bench，并用人类成对比较去反推各维度的权重。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频基础模型的瓶颈不在 DiT 的结构创新，而在于 token 便宜到什么程度、以及数据干净到什么程度。把 VAE 做小（127M）、做因果、做成可分块流式，token 就同时变便宜且不再限制时长；把数据清洗做成多级流水线并按运动质量分层采样，模型就不必用参数量去补数据的噪声。剩下的事情交给 DiT + flow matching 的 scaling law 去完成。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>Wan-VAE</strong>。输入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.888em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mtight">1</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mclose mtight">)</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span><span class="mbin mtight">×</span><span class="mord mtight">3</span></span></span></span></span></span></span></span></span></span></span></span>，压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/4</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord">/8</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mord">/8</span><span class="mclose">]</span></span></span></span>，通道扩到 16。首帧只做空间压缩（沿用 MagViT-v2 的做法），这样图像数据可以直接当作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 的特例处理。所有 GroupNorm 换成 RMSNorm 以保持时间因果性，从而使 feature cache 可用；空间上采样层的输入特征通道减半，推理显存降低 33%。调完 base channel 数后整个 VAE 只有 127M 参数。</p><p><strong>VAE 三阶段训练</strong>：先用同结构的 2D 图像 VAE 在图像上训好；再 inflate 成 3D causal VAE，带着空间压缩先验开始，比从零训视频 VAE 快得多，此阶段用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span>、5 帧的低分辨率短视频加速收敛，损失是 L1 重建（权重 3）+ KL（3e-6）+ LPIPS（3）；最后在多分辨率、多帧数的高质量视频上微调，并接入 3D 判别器的 GAN loss。</p><p><strong>feature cache</strong>。把视频切成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/4</span></span></span></span> 个 chunk，每块最多 4 帧，与 latent 帧数一一对应。默认因果卷积不改变帧数（kernel size 3），所以需要保留前一块的最后 2 帧特征；首块用两帧零填充初始化 cache。遇到 2× 时间下采样（stride 2）时，只对非首块做单帧 cache padding，以保证输出长度严格等于下采样比并跨块维持因果关系。这套机制让任意长度视频的编解码在固定显存下完成。</p><p><strong>DiT 主干</strong>。patchify 用 kernel <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mclose">)</span></span></span></span> 的 3D 卷积后展平，序列长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/4</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord">/16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mord">/16</span></span></span></span>。文本条件通过 cross-attention 注入，保证长上下文下仍能跟指令；时间步经 Linear + SiLU 的 MLP 预测六个 modulation 参数。AdaLN 采用全共享设计（PixArt 的 AdaLN-single 思路），在第一个 block 算一组全局参数供所有 block 复用。文本编码器是 umT5，embedding 序列长 512。</p><p><strong>训练目标</strong>是 rectified flow：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord mathnormal">t</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，真值速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 从 logit-normal 采样，损失是预测速度与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 MSE。</p><p><strong>训练课程</strong>：先在 256px 上做大规模 text-to-image 预训练，建立跨模态语义对齐与几何结构；再三阶段图文联合训练——(1) 256px 图像 + 192px / 16fps 的 5 秒视频，(2) 图像与视频同抬到 480px，(3) 抬到 720px。全程 bf16-mixed + AdamW（weight decay 1e-3），初始 lr 1e-4，按 FID 与 CLIP Score 的平台期动态下调。后训练保持同架构同优化器，从预训练 checkpoint 出发，在 480px 与 720px 上联合训练。</p><p><strong>数据流水线</strong>：先做基础维度过滤——OCR 文字覆盖率、LAION-5B 美学分类器、NSFW、水印/logo（训练时裁掉）、黑边、过曝、模糊、时长需超 4 秒；其中一条值得单独记：作者训了一个专家分类器专门剔除<strong>生成图像</strong>，因为经验上即便不到 10% 的生成图污染也会显著拖垮模型。这一层就砍掉约 50% 数据。随后是视觉质量：先聚成 100 个 cluster 再从每簇采样，避免长尾小类被整体分数淘汰；人工按 1–5 打分训练一个专家评分模型给全量数据打分。最后是运动质量，分六档——最优运动、中等质量运动、静态视频（访谈类，质量高但降采样率）、镜头驱动运动（航拍类，主体几乎不动，优先级大幅降低）、低质量运动（主体过多、遮挡严重）与手持抖动，后两类直接排除。视觉文字数据另开两路：在纯白底上渲染中文字符合成数亿张，再配上真实世界的含字图像。</p><p><strong>系统侧</strong>。text encoder 需要 20GB 以上显存，故做权重分片；DiT 用 FSDP 做参数分片，并用 2D Context Parallel（外层 Ring Attention、内层 Ulysses）。128 卡的例子里 CP=16（Ulysses 8 × Ring 2）、FSDP=32、DP=4。激活值用 offloading：一层 DiT 激活的 PCIe 传输时间可以被 1–3 层 DiT 的计算掩盖，再与 gradient checkpointing 组合，优先对显存/计算比高的层做 checkpoint。推理侧约 50 步采样，利用同一 DiT block 内跨步 attention 输出的相似性与后期 CFG 条件/无条件输出的相似性做 diffusion caching（含类 FasterCache 的残差补偿以免细节退化），14B T2V 提速 1.62×；FP8 GEMM（权重 per-tensor、激活 per-token 量化）让 GEMM 吞吐翻倍、DiT 提速 1.13×；8-bit FlashAttention 经 block size 调优后在 H20 上达到 95% MFU。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>Flow matching 把生成过程写成一条从噪声到数据的常微分方程轨迹，训练时只需在这条轨迹上做回归，避开了逐步预测的迭代结构。给定数据 latent <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、噪声 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.1474em;">N</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span></span></span></span> 与时间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6542em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>这是 Rectified Flow 的直线插值。沿这条直线，真值速度是常数：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="mord mathnormal">t</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>训练目标就是让网络回归这个速度：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2401em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2963em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">x</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="minner"><span class="mopen delimcenter" style="top:0em;">∥</span><span class="mord mathnormal">u</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">x</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;">∥</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></span></p><p>值得停一下的是为什么这个形式比预测噪声更好训。预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span> 时，任务难度随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 剧烈变化：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 接近 1 时几乎全是噪声，网络稳赚；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 接近 0 时又几乎不用做事。而直线插值下的速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 无关，网络在每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 上被要求的信息量更均衡，梯度尺度也更稳定。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 从 logit-normal 采样则进一步把采样密度压向中间的困难区。</p><p>计算开销一侧，论文给出 DiT 的成本表达式 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal">L</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mord mathnormal">b</span><span class="mord mathnormal">s</span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord mathnormal">b</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord mathnormal">h</span><span class="mclose">)</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 是层数、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span> 是 micro-batch、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 是序列长、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 是隐藏维；显存则是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mord mathnormal">L</span><span class="mord mathnormal">b</span><span class="mord mathnormal">s</span><span class="mord mathnormal">h</span></span></span></span>。这两个式子解释了为什么全部工程努力都指向压小 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 那一项是唯一的二次项。VAE 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 压缩加上 patchify 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mclose">)</span></span></span></span>，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/4</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord">/16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mord">/16</span></span></span></span>。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：VAE 是否兼顾质量与速度？</strong> 在 200 条 25 帧、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">720</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">720</span></span></span></span> 的视频上比 PSNR 与&quot;每单位延迟处理帧数&quot;。对照组包括 HunyuanVideo、CogVideoX（同为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、latent 16）、Open-Sora Plan（同压缩率但 latent 只有 4）、SVD（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、latent 4）、Step-Video（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span>、latent 64）、Mochi（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、latent 12）。结论是 Wan-VAE 在两个指标上同时具竞争力，重建速度是 HunyuanVideo 的 2.5 倍，且优势随分辨率提高而扩大。定性上分纹理、人脸、文字、高速运动四类场景验证。</p><p><strong>问题二：文本编码器该选谁？</strong> 固定其余设置、global batch 1536 训 text-to-image，对比 umT5(5.3B)、Qwen2.5-7B-Instruct、GLM-4-9B。结论是 umT5 收敛更快、组合性更好；即使按 HunyuanVideo 的做法给两个 LLM 加上双向 token refiner，训练损失与可视化仍是 umT5 占优。</p><p><strong>问题三：AdaLN 的参数该不该省下来换深度？</strong> 训 200,000 步 T2I（global batch 1536），比较四种配置：全共享 1.3B（30 层）、前半共享 1.5B、全共享但加深到 35 层的 1.5B、完全不共享的 1.7B。同参数量下全共享 + 更深（1.5B/35 层）训练损失最低；参数更多的非共享 1.7B 也没赢过它。结论是把预算花在深度上比花在 AdaLN 参数上划算，因此正式模型采用全共享 AdaLN。</p><p><strong>问题四：整体质量排在哪？</strong> Wan-Bench 拆成动态质量、图像质量、指令跟随三大类共 14 个细粒度指标，简单任务用传统检测器、复杂任务用 MLLM（Qwen2-VL）评判，例如相机运动分 pan / lift / zoom / 航拍 / 跟拍 五类共 130 条定制 prompt，前三类用 RAFT 光流判断、后两类用 Qwen2-VL 视频问答判断。总分的加权不取平均，而是收集 5,000 组以上人类成对比较，用模型打分与人评分的 Pearson 相关性反推各维权重。每个候选模型用 1,035 条 prompt 采样后评测，结果是 Wan 超过所列的商用与开源模型。</p><p>VBench 上，Wan 14B 总分 86.22%（画质 86.67%、语义 84.44%），高于 Sora 84.28%、MiniMax-Video-01 83.41%、HunyuanVideo 开源版 83.24%、Gen-3 82.32%、CogVideoX1.5-5B 82.17%、Kling 高性能模式 81.85%。Wan 1.3B 拿到 83.96%（画质 84.92%、语义 80.10%），已超过上面几个商用与开源条目。</p><p>一个不该被跳过的反向数据：在 Wan-Bench 的分维度表里，Large Motion Generation 一项 Wan 14B 是 0.415，低于 Sora 的 0.482，也低于自家 Wan 1.3B 的 0.468；Human Artifacts 一项 14B 是 0.691，低于表中最高的 0.833。也就是说 14B 的总分优势并非在每个维度上都成立。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：Wan 把开源视频模型的短板定义成性能、能力覆盖与消费级可用性三条，并按这三条组织全部工作。技术核心是一个 127M 的 3D 因果 VAE：RMSNorm 替换 GroupNorm 使 feature cache 成立，从而支持任意长度视频的分块流式编解码，重建速度是 HunyuanVideo VAE 的 2.5 倍。主干是 DiT + flow matching，AdaLN 全共享以把参数预算让给深度，文本用 umT5 而非更大的 decoder-only LLM。训练走 256px 图像 → 256/192px 联合 → 480px → 720px 的分辨率课程，数据经四级清洗并按六档运动质量分层采样。14B 在 VBench 拿到 86.22% 总分，1.3B 只需 8.19GB 显存。</p><p><strong>3 句话版</strong>：把 token 做便宜、把数据做干净，然后让 DiT + flow matching 的 scaling 生效。VAE 的因果化与 feature cache 同时解决了显存与任意时长。开源全套（含 1.3B 消费级档），因此成为后续 AR 与加速工作的默认底座。</p><p><strong>1 句话版</strong>：视频基础模型的开源缺口主要是系统与数据问题，不是架构问题。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>Wan-Bench 的人类偏好权重可以充当&quot;哪个模型更好&quot;的判据</strong>。整份报告里模型选型、消融取舍与最终排名都挂在这把尺子上，而这把尺子的构造方式是：用 Qwen2-VL 等 MLLM 给各维度打分，再用 5,000 组人类成对比较与这些分数的 Pearson 相关性作为权重。这里有一个循环风险——权重是按&quot;哪些自动指标与人评相关&quot;选出来的，而这些自动指标本身由 MLLM 产生，MLLM 的失败模式（对轻微伪影不敏感、偏好高饱和高清晰度画面）会同时污染分数与权重，且不会被 Pearson 相关性检出。</p><p>论文自己的数据给了一个耐人寻味的旁证：14B 在 Large Motion Generation 上反而不如 1.3B 与 Sora。若加权体系恰好给运动幅度较低的权重，那么&quot;更大更好&quot;这个结论就部分是权重选择的产物。作者提供的证据是那 5,000 组成对比较；缺的是对评测器本身的校准报告——例如 Qwen2-VL 在各维度上相对人工标注的准确率与失败模式分析。以上属于基于证据的推断，不是作者的声明。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>只测 VAE，一周内可完成，不需要碰 DiT。取公开的 Wan-VAE 权重与一批 200 条以上的长视频（至少 200 帧），做三件事：</p><ol><li><strong>验证 feature cache 的等价性</strong>。同一条视频分别用整段编码（在显存允许的短片上）与分块编码 + cache 两种方式，逐 latent 帧比较 L2 差异。若差异在数值误差量级，说明 cache 实现是精确的而非近似；若在 chunk 边界处出现周期性尖峰，则说明因果连续性只是近似维持。</li><li><strong>量化 RMSNorm 替换的代价</strong>。把权重里的 RMSNorm 换回 GroupNorm 是不可行的（需重训），但可以做一个替代测试：比较 chunk 边界帧与 chunk 内部帧的重建 PSNR 分布。若边界帧系统性更差，就定位到了 cache 机制的实际成本。</li><li><strong>复现 2.5× 速度声明</strong>。同硬件下对 Wan-VAE 与 HunyuanVideo VAE 计时，分辨率从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">480</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">480</span></span></span></span> 扫到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1280</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">720</span></span></span></span>，看加速比是否如论文所说随分辨率增大。</li></ol><p>支持/反驳判据：若 (1) 差异极小且 (2) 边界帧无系统性劣化，则&quot;任意长度流式编解码不以质量为代价&quot;这一关键声明成立；反之则说明长视频场景下存在论文未报告的累积失真。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者最有力的攻击不是质疑数字，而是给出替代解释：<strong>Wan 14B 的领先可能主要来自数据规模与清洗流水线，而 VAE、AdaLN 共享、umT5 这些设计只是让训练可行，并不解释质量优势</strong>。支持这一解释的证据来自论文自身：所有架构消融都是在 1.3B 上、以 200k 步 T2I 的训练 loss 为判据做的，而训练 loss 的微小差异与最终视频质量之间没有被验证过的映射；真正大规模的对照（同数据、换架构，训到 14B 规模）一次都没有做，成本上也可以理解。</p><p>具体攻击实验：固定 Wan 的数据流水线与训练课程，把 Wan-VAE 换成 HunyuanVideo 的 VAE（同为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、latent 16），其余全部不变，在 1.3B 规模上训到相同 token 预算，然后跑 Wan-Bench 与 VBench。若两者差距远小于 Wan 1.3B 与其他开源模型之间的差距，那么&quot;VAE 是核心贡献&quot;的定位就需要改写成&quot;VAE 是效率贡献&quot;——它买到的是速度与任意长度，不是质量。一个更狠的变体是反向做：把 Wan 的数据流水线套到 CogVideoX 的架构上，看排名是否随之翻转。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：Wan 的六档运动质量分层是一个静态的、人工定义的先验——哪一档采多少，是在训练前一次性拍板的。但论文自己的结果显示 14B 在 Large Motion Generation 上不升反降，这提示&quot;降低静态与镜头驱动视频采样率&quot;这类固定策略在不同模型规模下最优点并不相同：小模型可能受益于更干净的运动分布，大模型则可能被过度过滤掉的长尾运动饿到。</p><p><strong>新 framing</strong>：把训练数据的分层采样比例当成<strong>训练过程中的在线控制变量</strong>，而不是预处理阶段的超参。这不是&quot;加个数据增强&quot;，而是把数据配比与优化过程耦合起来——每一段训练窗口内，模型在哪一档运动上的 loss 下降最慢，就临时上调那一档的采样权重。可借鉴的相邻领域工具很成熟：LLM 预训练里的 domain reweighting（DoReMi 一类用小代理模型学各领域权重的方法）与 curriculum learning 里的 competence-based 调度。视频侧的额外优势是&quot;难度&quot;有物理量可代理——光流幅度、镜头切换密度、主体数量都是现成的分层轴。</p><p><strong>第一个实验</strong>：先证明&quot;最优配比随规模变化&quot;这个前提。在 1.3B 与一个更小的 0.5B 代理模型上，各训三组：Wan 的默认配比、把静态与镜头驱动档的采样率提高一倍、把最优运动档提高一倍。总 token 预算固定，训完各跑 Wan-Bench 的动态质量维度。若两个规模的最优配比不一致，就说明静态配比必然在某一端次优，随后即可上在线 reweighting，并以&quot;同预算下动态质量分&quot;作为净收益判据。</p>',62)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
